package dental.flow.api.adapters.rest.in.controller;
import dental.flow.api.adapters.rest.in.controller.dto.request.SaveDailyMapRequestDTO; import dental.flow.api.adapters.rest.in.controller.dto.response.*; import dental.flow.api.application.in.DailyMapUseCase; import dental.flow.api.boot.exception.*; import dental.flow.api.boot.security.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.List;
@RestController @RequestMapping("/daily-map") public class DailyMapController { private final DailyMapUseCase service; public DailyMapController(DailyMapUseCase service){this.service=service;}
 @PostMapping public ResponseEntity<ApiResponse<DailyMapResponseDTO>> create(@RequestBody SaveDailyMapRequestDTO request){var u=user();return ResponseEntity.status(201).body(ApiResponse.created("Mapa diário criado com sucesso.",service.create(u.clinicId(),u.dentistId(),u.userId(),request)));}
 @PutMapping("/{id}") public ResponseEntity<ApiResponse<DailyMapResponseDTO>> update(@PathVariable Long id,@RequestBody SaveDailyMapRequestDTO request){var u=user();return ResponseEntity.ok(ApiResponse.ok("Mapa diário atualizado com sucesso.",service.update(id,u.clinicId(),u.dentistId(),u.userId(),request)));}
 @GetMapping("/{id}") public ResponseEntity<ApiResponse<DailyMapResponseDTO>> get(@PathVariable Long id){var u=user();return ResponseEntity.ok(ApiResponse.ok("Mapa diário consultado com sucesso.",service.get(id,u.clinicId(),u.dentistId())));}
 @GetMapping(params="date") public ResponseEntity<ApiResponse<DailyMapResponseDTO>> getByDate(@RequestParam LocalDate date){var u=user();return ResponseEntity.ok(ApiResponse.ok("Mapa diário consultado com sucesso.",service.getByDate(date,u.clinicId(),u.dentistId())));}
 @GetMapping public ResponseEntity<ApiResponse<List<DailyMapResponseDTO>>> list(@RequestParam LocalDate start,@RequestParam LocalDate end){var u=user();return ResponseEntity.ok(ApiResponse.ok("Mapas diários consultados com sucesso.",service.list(start,end,u.clinicId(),u.dentistId())));}
 @PatchMapping("/{id}/close") public ResponseEntity<ApiResponse<DailyMapResponseDTO>> close(@PathVariable Long id){var u=user();return ResponseEntity.ok(ApiResponse.ok("Mapa diário fechado com sucesso.",service.close(id,u.clinicId(),u.dentistId(),u.userId())));}
 private DentalFlowUserPrincipal user(){DentalFlowUserPrincipal u=ClinicAccess.currentUser();if(u.dentistId()==null)throw new BusinessException(Failures.BUSINESS_FAILURE,"Usuário sem vínculo com dentista.");return u;}
}
